package com.chatsystem.admin.controller;

import com.chatsystem.admin.navigation.*; import com.chatsystem.admin.ui.DisabledControlSupport; import com.chatsystem.shared.service.AdminService; import com.chatsystem.shared.validation.ValidationResult;
import javafx.fxml.FXML; import javafx.scene.control.*; import javafx.scene.layout.StackPane; import java.time.*; import java.time.temporal.TemporalUnit; import java.util.Objects;
public final class DashboardController implements DisposableController {
 private final AdminService service; private final AdminNavigator navigator;
 private final javafx.beans.value.ChangeListener<AdminService.DashboardMetrics> metricsListener=(o,a,b)->refresh(); @FXML private Label usersMetric,groupsMetric,reportsMetric,messagesMetric,snapshotLabel; @FXML private Button exportButton,viewUsersButton,viewGroupsButton,viewModerationButton; @FXML private MenuButton rangeButton; @FXML private ListView<AdminService.DailyActivity> activityTrend; @FXML private ListView<String> recentActivity; @FXML private StackPane exportWrapper;
 public DashboardController(AdminService service,AdminNavigator navigator){this.service=Objects.requireNonNull(service);this.navigator=Objects.requireNonNull(navigator);}
 @FXML private void initialize(){ activityTrend.setCellFactory(ignored->new com.chatsystem.admin.ui.ActivityBarCell());if(exportButton!=null)DisabledControlSupport.install(exportButton,exportWrapper,exportReason());for(int days:new int[]{7,30,365}){MenuItem item=new MenuItem("Last "+days+" days");item.setOnAction(e->{selectRange(days,java.time.temporal.ChronoUnit.DAYS);rangeButton.setText(item.getText()+"  v");});rangeButton.getItems().add(item);}selectRange(30,java.time.temporal.ChronoUnit.DAYS);rangeButton.setText("Last 30 days  v");refresh(); if(viewUsersButton!=null){viewUsersButton.setOnAction(e->showUsers());viewGroupsButton.setOnAction(e->showGroups());viewModerationButton.setOnAction(e->showModeration());} service.metricsProperty().addListener(metricsListener); }
 private void refresh(){if(usersMetric!=null){var m=metrics();usersMetric.setText(Long.toString(m.totalUsers()));groupsMetric.setText(Long.toString(m.totalGroups()));reportsMetric.setText(Long.toString(m.pendingReports()));messagesMetric.setText(Long.toString(m.messageCount()));activityTrend.setItems(service.getActivityTrend());snapshotLabel.setText(m.activeUsers()+" active  •  "+m.lockedUsers()+" restricted  •  "+m.pendingReports()+" pending warnings");recentActivity.setItems(javafx.collections.FXCollections.observableArrayList("Latest registration: "+service.getUsers().get(service.getUsers().size()-1).getDisplayName(),"Pending warning reports: "+m.pendingReports(),"Communities created: "+m.totalGroups(),"Accounts currently restricted: "+m.lockedUsers()));}}
 public AdminService.DashboardMetrics metrics(){return service.getMetrics();}
 public ValidationResult<Void> selectRange(long amount,TemporalUnit unit){Instant end=com.chatsystem.shared.mock.MockFixtures.REFERENCE_TIME.plusSeconds(1);return service.setDateRange(end.minus(amount,unit),end);}
 public void showUsers(){navigator.navigate(ViewRequest.of(AdminRoute.USERS));} public void showGroups(){navigator.navigate(ViewRequest.of(AdminRoute.GROUPS));} public void showModeration(){navigator.navigate(ViewRequest.of(AdminRoute.MODERATION));}
 public String exportReason(){return "Overview export is unavailable in the frontend-only demo.";}
 public void dispose(){service.metricsProperty().removeListener(metricsListener);}
}
